package com.example.mydailyroutine
import android.app.*;import android.content.*;import android.media.RingtoneManager;import android.os.Build
class AlarmReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val ch="routine_alarm";val n=c.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;if(Build.VERSION.SDK_INT>=26){val x=NotificationChannel(ch,"Routine alarms",NotificationManager.IMPORTANCE_HIGH);x.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM),null);x.enableVibration(true);n.createNotificationChannel(x)};val id=i.getIntExtra("id",0);val title=i.getStringExtra("title")?:"এখন আপনার কাজের সময়";val snooze=PendingIntent.getBroadcast(c,1000+id,Intent(c,SnoozeReceiver::class.java).putExtra("id",id).putExtra("title",title),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val done=PendingIntent.getBroadcast(c,2000+id,Intent(c,ClearReceiver::class.java).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);n.notify(id,Notification.Builder(c,ch).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("My Daily Routine").setContentText(title).setAutoCancel(true).addAction(Notification.Action.Builder(null,"😴 Snooze 10 min",snooze).build()).addAction(Notification.Action.Builder(null,"✅ Done",done).build()).build());scheduleNext(c,id)};private fun scheduleNext(c:Context,id:Int){val p=c.getSharedPreferences("routine",0);val d=MainDefaults.v[id];Scheduler(c).set(Routine(id,p.getInt("h$id",d.hour),p.getInt("m$id",d.minute),p.getString("t$id",d.title)?:d.title,d.emoji,p.getBoolean("e$id",true)))}
}
object MainDefaults{val v=listOf(Routine(0,6,30,"ঘুম থেকে ওঠা","⏰"),Routine(1,6,40,"ফ্রেশ হওয়া","🧼"),Routine(2,7,0,"নামাজ/প্রার্থনা ও শান্ত সময়","🕌"),Routine(3,7,30,"হাঁটা/ব্যায়াম","🏃"),Routine(4,8,0,"নাশতা","🍳"),Routine(5,8,30,"আজকের কাজের পরিকল্পনা","📋"),Routine(6,9,0,"প্রধান কাজ/পড়াশোনা","💼"),Routine(7,13,0,"দুপুরের খাবার","🍛"),Routine(8,13,30,"বিশ্রাম","😌"),Routine(9,14,0,"কাজ/পড়াশোনা","💼"),Routine(10,17,0,"নাস্তা + বিশ্রাম","☕"),Routine(11,17,30,"হাঁটা/ব্যক্তিগত কাজ","🚶"),Routine(12,18,30,"প্রয়োজনীয় ফোন/অনলাইন কাজ","📱"),Routine(13,19,30,"নামাজ/প্রার্থনা","🕌"),Routine(14,20,0,"রাতের খাবার","🍽️"),Routine(15,20,30,"পরিবার/নিজের সময়","👨‍👩‍👦"),Routine(16,21,30,"ফোন কমানো","📱"),Routine(17,22,0,"ঘুমের প্রস্তুতি","🧼"),Routine(18,22,30,"হালকা পড়া/পরের দিনের পরিকল্পনা","📖"),Routine(19,23,0,"ঘুম","😴"))}
class ClearReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){(c.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager).cancel(i.getIntExtra("id",0))}}
class SnoozeReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val id=i.getIntExtra("id",0);val title=i.getStringExtra("title")?:"Reminder";val a=c.getSystemService(Context.ALARM_SERVICE) as AlarmManager;val pi=PendingIntent.getBroadcast(c,3000+id,Intent(c,AlarmReceiver::class.java).putExtra("id",id).putExtra("title","⏰ Snooze শেষ — $title"),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+600000,pi)}}
